    "src/Interfaces/ICollateralVault.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import "./IDToken.sol";
import "./IStrategy.sol";

/**
 * @title ICollateralVault - Collateral custody, redemption & yield-allocation interface (push model)
 * @notice Full push-model surface: the dToken入出金 core (deposit / redeem /
 *         redeemWithPermit / claim, buffer + withdraw config, pause) PLUS the
 *         Strategy / yield layer added in Phase 3b (allocate /
 *         receiveFromStrategy / transferYieldToTreasury / strategy whitelist +
 *         CRUD / writeoff / allocation pause / strategy views). The
 *         deferred-underlying binding for placeholder branches
 *         (`setUnderlying` + `UnderlyingSet`) is part of this interface.
 * @dev    `StrategyConfig` carries no `isAsyncWithdraw`: synchronous vs.
 *         asynchronous handling is encapsulated inside each Strategy
 *         implementation (push model). The Vault reserves the push-model
 *         storage layout from Phase 3a, so the Phase 3b surface below is
 *         purely additive.
 */
interface ICollateralVault {
    // --- Structs ---

    /// @notice Per-Strategy configuration (push model).
    struct StrategyConfig {
        bool enabled;
        uint256 weightBps;
        uint256 cap;
    }

    /// @notice Fail-soft per-Strategy monitoring snapshot.
    struct StrategyStatus {
        IStrategy strategy;
        StrategyConfig config;
        uint256 estimatedUnderlying;
        uint256 principal;
        uint256 conservativeValue;
        uint256 cachedConservativeValue;
        uint256 cacheUpdatedAt;
        uint256 estimatedGain;
        uint256 estimatedLoss;
        uint256 capRemaining;
        bool estimateAvailable;
        bool principalAvailable;
        bool usingCachedConservativeValue;
        bool cacheAvailable;
        bool cacheStale;
    }

    /// @notice Last successful per-Strategy conservative valuation snapshot.
    struct StrategyValuationCache {
        uint256 conservativeValue;
        uint256 updatedAt;
        bool initialized;
    }

    struct WithdrawRequest {
        address owner;
        uint256 underlyingAmount;
        uint256 claimableAt;
        bool claimed;
    }

    // --- Events (dToken portion) ---

    event Deposited(address indexed user, uint256 underlyingAmount, uint256 dTokenAmount);
    event Redeemed(
        address indexed user,
        address indexed receiver,
        uint256 dTokenAmount,
        uint256 underlyingPaidNow,
        uint256 requestId
    );
    event WithdrawRequested(
        address indexed user, address indexed receiver, uint256 requestId, uint256 amount, uint256 claimableAt
    );
    event WithdrawClaimed(address indexed user, uint256 requestId, uint256 amount);

    event DepositPaused();
    event DepositUnpaused();
    event RedeemPaused();
    event RedeemUnpaused();
    event ClaimPaused();
    event ClaimUnpaused();

    /// @notice Emitted once when a placeholder Vault's underlying is bound via `setUnderlying`.
    event UnderlyingSet(address indexed underlying);

    // --- Events (Strategy / yield layer) ---

    event StrategyWhitelisted(address indexed strategy);
    event StrategyRemovedFromWhitelist(address indexed strategy);
    event StrategyAdded(address indexed strategy, uint256 weightBps, uint256 cap);
    event StrategyUpdated(address indexed strategy, uint256 weightBps, uint256 cap, bool enabled);
    event StrategyEmergencyDisabled(address indexed strategy, uint256 oldWeightBps);
    event StrategyRemoved(address indexed strategy);
    event StrategyPrincipalWrittenOff(address indexed strategy, uint256 amount);
    event MorphoV2ForceDeallocated(
        address indexed strategy,
        address indexed adapter,
        uint256 assets,
        uint256 penaltyShares,
        uint256 penaltyAssets,
        uint256 valuationLossAssets,
        uint256 backingRatioAfter
    );
    event StrategyValuationMaxAgeUpdated(uint256 oldMaxAge, uint256 newMaxAge);
    event StrategyValuationGasBudgetUpdated(uint256 oldBudget, uint256 newBudget);
    event StrategyValuationRefreshed(
        address indexed strategy, uint256 estimatedUnderlying, uint256 principal, uint256 conservativeValue
    );
    event StrategyValuationRefreshFailed(address indexed strategy, bool estimateAvailable, bool principalAvailable);
    event StrategyValuationCacheReduced(address indexed strategy, uint256 oldValue, uint256 newValue, uint256 amount);
    event StrategyValuationCacheInvalidated(address indexed strategy, uint256 oldValue, uint256 oldUpdatedAt);

    event Allocated(uint256 bufferBefore, uint256 targetBuffer, uint256 bufferAfter);
    event StrategyAllocated(address indexed strategy, uint256 amount);
    event StrategyAllocationSkipped(address indexed strategy);
    event ReceivedFromStrategy(address indexed strategy, uint256 declaredAmount, uint256 received);
    event YieldTransferredToTreasury(uint256 amount, address indexed treasury);
    event BackstopDeposited(address indexed backstop, uint256 declaredAmount, uint256 received);
    event BackstopReleased(address indexed caller, uint256 amount);

    event AllocationPaused();
    event AllocationUnpaused();
    event BufferConfigUpdated(uint256 oldTargetBps, uint256 newTargetBps, uint256 oldFloor, uint256 newFloor);
    event AllocatorConfigUpdated(uint256 oldMaxMove, uint256 newMaxMove, uint256 oldCooldown, uint256 newCooldown);
    event WithdrawDelayUpdated(uint256 oldDelay, uint256 newDelay);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    // --- View Functions ---

    function underlying() external view returns (IERC20);
    function dToken() external view returns (IDToken);
    function treasury() external view returns (address);
    function bufferBalance() external view returns (uint256);
    function backstopBalance() external view returns (uint256);
    function totalUnderlying() external view returns (uint256);
    function bufferTargetBps() external view returns (uint256);
    function bufferFloor() external view returns (uint256);
    function pausedDeposit() external view returns (bool);
    function pausedRedeem() external view returns (bool);
    function pausedClaim() external view returns (bool);
    function pausedAllocation() external view returns (bool);
    function pendingWithdrawals() external view returns (uint256);
    function strategyValuationMaxAge() external view returns (uint256);
    /// @notice Gas forwarded to each Strategy valuation probe (`estimatedTotalUnderlying`, `principal`).
    function strategyValuationGasBudget() external view returns (uint256);
    function strategyValuationCaches(IStrategy _strategy)
        external
        view
        returns (uint256 conservativeValue, uint256 updatedAt, bool initialized);
    function actualLiabilities() external view returns (uint256);
    function backingRatio() external view returns (uint256);
    /// @notice Backing ratio for price-feed consumption, with valuation availability.
    /// @dev `available == false` means at least one registered Strategy had
    ///      neither a live valuation nor a fresh cache. Feeds must treat this as
    ///      oracle failure, not as a measured total loss.
    ///      Availability remains true when known assets cover all liabilities,
    ///      even if another Strategy cannot be valued.
    function backingRatioForPricing() external view returns (uint256 ratio, bool available);

    // --- User Functions ---

    function deposit(uint256 _underlyingAmount) external returns (uint256 dTokenAmount);

    /// @notice Burn dToken and pay Underlying to `_receiver` immediately or by
    ///         delayed request. `underlyingReceived` is the receiver's measured
    ///         immediate balance increase, not the nominal transfer argument.
    function redeem(uint256 _dTokenAmount, address _receiver)
        external
        returns (uint256 underlyingReceived, uint256 requestId);

    function redeemWithPermit(
        uint256 _dTokenAmount,
        uint256 _deadline,
        uint8 _v,
        bytes32 _r,
        bytes32 _s,
        address _receiver
    ) external returns (uint256 underlyingReceived, uint256 requestId);

    /// @notice Settle a matured withdrawal request to its recorded owner.
    /// @dev Anyone may trigger settlement, but the caller cannot redirect the payment.
    ///      Returns zero without another transfer when the request is already settled.
    function claim(uint256 _requestId) external returns (uint256 underlyingClaimed);

    /// @notice Add underlying to the Vault's protected backstop reserve without minting dToken.
    /// @dev Intended for Treasury / insurance / backstop repair. The credited
    ///      amount is measured by balance diff, matching `receiveFromStrategy`,
    ///      and is reserved from `bufferBalance()` until GOV releases it.
    function backstopDeposit(uint256 _underlyingAmount) external returns (uint256 received);

    /// @notice Release reserved backstop underlying into the liquid redemption buffer. GOV_ROLE.
    /// @dev No asset transfer occurs; this only moves accounting from
    ///      `backstopBalance()` to `bufferBalance()` after an explicit repair
    ///      decision.
    function releaseBackstopToBuffer(uint256 _amount) external returns (uint256 released);

    // --- Deferred-binding Activation ---

    /// @notice Bind a placeholder Vault's underlying once. GOV_ROLE.
    /// @dev Requires `dToken.underlying() == _underlying` (dToken-first ordering).
    function setUnderlying(IERC20 _underlying) external;

    // --- Allocator Functions ---

    /// @notice Allocate buffer excess to strategies. ALLOCATOR_ROLE.
    /// @dev    Deallocation (the "amount-specified push") lives on the Strategy
    ///         side as `Strategy.sendToVault(uint256)`; the ALLOCATOR calls that
    ///         directly. There is no `deallocate` here.
    function allocate() external;

    // --- Strategy → Vault Push (called by a registered Strategy) ---

    /// @notice Receive underlying pushed from a registered Strategy. Pulls
    ///         `_declaredAmount` from the caller via `safeTransferFrom` and
    ///         credits the Vault buffer; the actual amount is measured by the
    ///         Vault balance diff (so fee-on-transfer underlyings are accounted
    ///         by real receipt). The Vault does not distinguish principal from
    ///         yield here — use `transferYieldToTreasury` for the surplus. A
    ///         declared/received mismatch invalidates the Strategy valuation
    ///         cache instead of preserving an ambiguous fallback value.
    function receiveFromStrategy(uint256 _declaredAmount) external returns (uint256 received);

    // --- Yield / Treasury Functions ---

    /// @notice Send the managed-asset surplus over current liabilities to the treasury.
    ///         TREASURY_TRANSFER_ROLE. Computes
    ///         `managedUnderlying - (dToken backing + pendingWithdrawals)` using the
    ///         liquid buffer plus conservative per-Strategy view
    ///         `min(estimatedTotalUnderlying, principal)`, explicitly excluding
    ///         protected backstop reserve and capping at the current buffer above
    ///         the same liquidity reserve kept by `allocate`
    ///         (`max(managedUnderlying * bufferTargetBps / 10000, bufferFloor) +
    ///         pendingWithdrawals`).
    function transferYieldToTreasury() external returns (uint256 transferred);

    // --- Governance Functions (Strategy layer) ---

    function addToWhitelist(address _strategy) external;
    /// @notice Remove a strategy from the allowlist. If the strategy is already
    ///         registered, this also disables future allocation to it.
    function removeFromWhitelist(address _strategy) external;
    function addStrategy(IStrategy _strategy, uint256 _weightBps, uint256 _cap) external;
    function updateStrategy(IStrategy _strategy, uint256 _weightBps, uint256 _cap, bool _enabled) external;
    function emergencyDisableStrategy(IStrategy _strategy) external;

    /// @notice Remove a Strategy from registration. Requires the Strategy's
    ///         `principal()` and live `estimatedTotalUnderlying()` to both be
    ///         readable and zero (drain via `Strategy.sendToVault` first, or
    ///         `writeoffStrategyPrincipal` for a permanent loss).
    function removeStrategy(IStrategy _strategy) external;

    /// @notice Acknowledge a permanent loss of principal on a Strategy so that
    ///         `removeStrategy` can later succeed.
    /// @dev Requires the Strategy to be disabled, or allocation to be paused,
    ///      before live principal can be written off. Reverts if the post-writeoff
    ///      `backingRatio()` would be below `_minBackingRatioAfter`; callers should
    ///      set this from an incident dry-run to prevent over-markdown / state drift.
    function writeoffStrategyPrincipal(IStrategy _strategy, uint256 _amount, uint256 _minBackingRatioAfter) external;

    /// @notice Atomically force-deallocate Morpho V2 liquidity and recover it
    ///         to this Vault with a bounded penalty. WRITEOFF_ROLE only.
    /// @dev Atomically pauses allocation and user Vault flows, calls the
    ///      registered Strategy, and refreshes/reduces its valuation cache.
    ///      Reverts the penalty and recovery together if actual Vault receipt
    ///      is below the nonzero minimum or post-loss backing is below its floor.
    function forceDeallocateMorphoV2(
        IStrategy _strategy,
        address _adapter,
        bytes calldata _data,
        uint256 _assets,
        uint256 _minReceived,
        uint256 _minBackingRatioAfter
    ) external returns (uint256 penaltyShares, uint256 penaltyAssets, uint256 valuationLossAssets);

    function setAllocatorConfig(uint256 _maxMove, uint256 _cooldown) external;
    function setStrategyValuationMaxAge(uint256 _maxAge) external;
    /// @notice Retune the per-probe Strategy valuation gas budget. GOV_ROLE; bounded to [100_000, 2_000_000].
    function setStrategyValuationGasBudget(uint256 _budget) external;
    function refreshStrategyValuation(IStrategy _strategy) external returns (bool refreshed);
    /// @notice Drop a Strategy's fallback valuation cache. GOV_ROLE, or WRITEOFF_ROLE after allocation is paused
    ///         or the Strategy is disabled.
    /// @dev Incident response path for stale cache removal when live Strategy
    ///      valuation is unavailable. This can only make solvency views more
    ///      conservative until a fresh live valuation succeeds.
    function invalidateStrategyValuationCache(IStrategy _strategy) external;

    // --- Governance Functions (dToken portion) ---

    function setBufferConfig(uint256 _targetBps, uint256 _floor) external;
    function setWithdrawDelay(uint256 _delay) external;
    function setTreasury(address _treasury) external;
    function pauseDeposit() external;
    function unpauseDeposit() external;
    function pauseRedeem() external;
    function unpauseRedeem() external;
    function pauseClaim() external;
    function unpauseClaim() external;
    function pauseAllocation() external;
    function unpauseAllocation() external;

    // --- Strategy Management View Functions ---

    function MAX_STRATEGIES() external view returns (uint256);
    function getStrategiesCount() external view returns (uint256);
    function strategies(uint256 index) external view returns (IStrategy);
    function strategyConfigs(IStrategy strategy) external view returns (bool enabled, uint256 weightBps, uint256 cap);
}
"
    },
    "src/Interfaces/IDToken.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "openzeppelin-contracts-upgradeable/token/ERC20/extensions/IERC20MetadataUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/token/ERC20/extensions/IERC20PermitUpgradeable.sol";

/**
 * @title IDToken - Collateral Benefit Token Interface
 * @notice ERC-20 token representing a 1:1 principal claim on Underlying
 * @dev decimals fixed at 18 (per Liquity v2 requirements)
 */
interface IDToken is IERC20MetadataUpgradeable, IERC20PermitUpgradeable {
    /// @notice Corresponding Underlying token
    function underlying() external view returns (IERC20MetadataUpgradeable);

    /// @notice Vault address that issues this dToken
    function vault() external view returns (address);

    /// @notice Underlying token decimals
    function underlyingDecimals() external view returns (uint8);

    /// @notice Maximum supply cap for dToken
    function cap() external view returns (uint256);

    /// @notice Core registry bound once before minting; zero means issuance is unavailable.
    function riskParamsRegistry() external view returns (address);

    /// @notice Bind the matching Core registry once while cap and supply are zero (Owner only).
    /// @dev Nonzero caps and minting require this registry's riskParamsFinalized to be true.
    function setRiskParamsRegistry(address _registry) external;

    /// @notice Whether an underlying token is allowed for this dToken.
    function allowedUnderlying(address _underlying) external view returns (bool);

    /**
     * @notice Convert UnderlyingAmount to dTokenAmount
     * @param _underlyingAmount Amount of Underlying
     * @return dTokenAmount amount (18 decimals)
     */
    function convertToDToken(uint256 _underlyingAmount) external view returns (uint256);

    /**
     * @notice Convert dTokenAmount to UnderlyingAmount
     * @param _dTokenAmount dToken amount (18 decimals)
     * @return underlyingAmount amount
     */
    function convertToUnderlying(uint256 _dTokenAmount) external view returns (uint256);

    /**
     * @notice Mint dToken (Vault only)
     * @param _to Recipient address
     * @param _amount Mint amount
     * @dev Reverts if cap is exceeded
     */
    function mint(address _to, uint256 _amount) external;

    /**
     * @notice Burn dToken (Vault only)
     * @param _from Address to burn from
     * @param _amount Burn amount
     */
    function burn(address _from, uint256 _amount) external;

    /**
     * @notice Set the maximum supply cap for dToken (Admin only)
     * @param _newCap New cap value (18 decimals)
     */
    function setCap(uint256 _newCap) external;

    /**
     * @notice Allow or disallow an underlying asset before token info is bound (Admin only)
     * @param _underlying Underlying token address
     * @param _allowed Whether the token is allowed
     */
    function setAllowedUnderlying(address _underlying, bool _allowed) external;

    /**
     * @notice Set token name, symbol, and underlying asset (Admin only)
     * @param _newName Token name
     * @param _newSymbol Token symbol
     * @param _underlying Corresponding Underlying token
     */
    function setTokenInfo(string memory _newName, string memory _newSymbol, IERC20MetadataUpgradeable _underlying)
        external;
}
"
    },
    "src/Interfaces/IStrategy.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";

/**
 * @title IStrategy - Common interface for yield strategies (push model)
 * @notice Strategies expose two push functions. They withdraw underlying internally
 *         and call back into the Vault via `receiveFromStrategy` for principal
 *         pushes; realized yield is transferred directly to the Vault buffer.
 *         The upstream yield protocol can be synchronous or asynchronous.
 * @dev
 *   - `sendToVault(uint256)` is the "amount-specified push" used by the
 *     ALLOCATOR role on the Vault. It is the replacement for the old
 *     `Vault.deallocate(...)` flow.
 *   - `sendProfitToVault()` is the "profit-capped push", also gated by the
 *     ALLOCATOR role on the Vault. The amount is internally capped at `realizedYield()`.
 *   - Both functions are role-gated by querying the Vault's AccessControl, so
 *     a single role registry (on the Vault) governs both.
 *   - `principal()` is the per-Strategy bookkeeping of cumulative deposits
 *     minus principal-portion withdrawals. The Vault uses
 *     `min(estimatedTotalUnderlying, principal)` for the solvency view.
 */
interface IStrategy {
    /// @notice Underlying token address used by this Strategy
    function underlying() external view returns (address);

    /// @notice Receive underlying that has already been transferred by the Vault
    ///         and deploy it to the upstream yield protocol.
    /// @dev    onlyVault. The Vault transfers underlying *before* calling this.
    /// @param  _declaredAmount Amount removed from the Vault buffer
    /// @param  _receivedAmount Net amount received by the Strategy
    /// @return deposited `_receivedAmount` when deployed, or 0 after exact recovery to the Vault
    function deposit(uint256 _declaredAmount, uint256 _receivedAmount) external returns (uint256 deposited);

    /// @notice Principal currently tracked by this Strategy
    ///         (cumulative deposit minus the principal-portion of withdrawals).
    function principal() external view returns (uint256);

    /// @notice `estimatedTotalUnderlying() - principal()` clamped at zero.
    ///         Used as the cap by `sendProfitToVault()`.
    function realizedYield() external view returns (uint256);

    /// @notice Current estimated underlying value held by this Strategy.
    function estimatedTotalUnderlying() external view returns (uint256);

    /// @notice Push underlying back to the Vault. Caller must hold the
    ///         WITHDRAWER_ROLE on the Vault. Used for deallocation /
    ///         portfolio rebalancing / removeStrategy preparation.
    /// @param  _amount Requested amount. The actual sent amount may be less
    ///         if the upstream protocol cannot fulfill the full request.
    /// @return sent   Amount actually received by the Vault.
    function sendToVault(uint256 _amount) external returns (uint256 sent);

    /// @notice Push only realized yield to the Vault. Caller must hold the
    ///         HARVESTER_ROLE on the Vault. The amount is computed by the
    ///         Strategy as `realizedYield()` at call time; the caller does
    ///         not supply an amount.
    /// @return sent   Amount actually received by the Vault.
    function sendProfitToVault() external returns (uint256 sent);

    /// @notice Acknowledge a permanent loss of principal so that the Strategy
    ///         can be removed even though `estimatedTotalUnderlying()` is
    ///         below `principal()`. Vault-only.
    /// @param  _amount Amount of principal to write off.
    /// @return writtenOff Amount actually written off after clamping to principal.
    function writeoffPrincipal(uint256 _amount) external returns (uint256 writtenOff);

    /// @notice Sweep non-underlying, non-position reward tokens held by this
    ///         Strategy to the Vault's current treasury. Owner-only in the implementation.
    /// @dev    Must reject the Strategy underlying and protocol position /
    ///         accounting tokens so this cannot bypass the normal Vault-return
    ///         path for principal or underlying yield. Pass `type(uint256).max`
    ///         to sweep the full Strategy token balance.
    /// @param  _token Reward token to sweep.
    /// @param  _amount Requested amount to transfer.
    /// @return swept Amount actually received by the treasury, measured by
    ///         balance diff to support fee-on-transfer reward tokens.
    function sweepRewardToken(IERC20 _token, uint256 _amount) external returns (uint256 swept);
}
"
    },
    "src/Strategies/AaveV3Strategy.sol": {
      "content": "// SPDX-License-Identifier: BUSL-1.1

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/utils/math/Math.sol";

import "./BaseStrategy.sol";

/**
 * @title IAaveV3Pool - Aave V3 Pool Interface (minimal)
 */
interface IAaveV3Pool {
    function supply(address asset, uint256 amount, address onBehalfOf, uint16 referralCode) external;

    function withdraw(address asset, uint256 amount, address to) external returns (uint256);

    /// @notice Returns the normalized income of the reserve, in RAY (1e27).
    ///         underlying = scaled * income / RAY.
    function getReserveNormalizedIncome(address asset) external view returns (uint256);
}

/**
 * @title IAaveRewardsController - Aave V3 rewards interface (minimal)
 */
interface IAaveRewardsController {
    function claimRewards(address[] calldata assets, uint256 amount, address to, address reward)
        external
        returns (uint256);
}

/**
 * @title IAToken - Aave aToken Interface (minimal)
 */
interface IAToken {
    function balanceOf(address account) external view returns (uint256);

    /// @notice Scaled balance (RAY-precision share of the reserve). Unaffected
    ///         by interest accrual; changes only on supply / withdraw / transfer.
    function scaledBalanceOf(address account) external view returns (uint256);

    function UNDERLYING_ASSET_ADDRESS() external view returns (address);
}

/**
 * @title AaveV3Strategy - Aave V3 Lending Strategy (push model, Upgradeable)
 * @notice Synchronous lending strategy backed by Aave V3.
 *         Withdrawals are immediate up to the reserve's currently liquid
 *         underlying; `_doWithdraw` pulls underlying into this contract. The
 *         BaseStrategy then routes principal returns through
 *         `receiveFromStrategy` and yield-only pushes through a direct transfer
 *         to the Vault buffer.
 * @dev    The Strategy tracks the scaled-balance share that **this contract**
 *         accumulated via its own `supply` / `withdraw` calls. The Aave V3
 *         `Pool.supply(asset, X, onBehalfOf = AaveV3Strategy, 0)` entry point
 *         is permissionless, so anyone can credit additional aToken to this
 *         contract. To prevent such "donations" from inflating
 *         `realizedYield()` (which would let an adversary route arbitrary
 *         amounts into `treasury` via
 *         `sendProfitToVault` + `transferYieldToTreasury`),
 *         `_estimatedTotalUnderlying()` is computed from the locally tracked
 *         scaled balance rather than `aToken.balanceOf`.
 */
contract AaveV3Strategy is BaseStrategy {
    using SafeERC20 for IERC20;

    // =============================================================
    //                         STATE
    // =============================================================

    IAaveV3Pool public aavePool;
    IAToken public aToken;

    /// @notice Scaled balance (RAY-precision) that this contract minted
    ///         through its own `supply` calls minus what was burned through
    ///         its own `withdraw` calls. Donations made by third parties via
    ///         `supply(_, _, onBehalfOf=this, _)` do NOT affect this value,
    ///         so `_estimatedTotalUnderlying()` reflects only the Strategy's
    ///         own share of the reserve.
    uint256 internal _ownScaledBalance;

    /// @dev Storage gap for future upgrades of this derived contract.
    uint256[48] private __gapAaveV3;

    /// @dev Aave V3 normalized-income / scaled-balance precision.
    uint256 internal constant _RAY = 1e27;

    // =============================================================
    //                          EVENTS
    // =============================================================

    event OwnScaledBalanceUpdated(uint256 newScaledBalance);
    event AaveRewardsClaimed(
        address indexed rewardsController, address indexed reward, uint256 requested, uint256 claimed, uint256 settled
    );
    event AaveUnderlyingRewardsClaimed(
        address indexed rewardsController,
        address indexed reward,
        uint256 requested,
        uint256 claimed,
        uint256 sentToVault
    );

    // =============================================================
    //                        INITIALIZER
    // =============================================================

    error InvalidATokenUnderlying();
    error InvalidAaveRewardsController();
    error AaveSupplyZeroScaledBalance(uint256 amount);
    error AaveWithdrawZeroScaledBurn(uint256 actual);
    error AaveWithdrawZeroReported(uint256 actual);

    function initialize(
        address _vault,
        IERC20 _underlying,
        address _owner,
        address _upgrader,
        IAaveV3Pool _aavePool,
        IAToken _aToken
    ) external initializer {
        __BaseStrategy_init(_vault, _underlying, _owner, _upgrader);

        if (address(_aavePool) == address(0)) revert ZeroAddress();
        if (address(_aToken) == address(0)) revert ZeroAddress();
        if (address(_aavePool).code.length == 0) revert NotContract(address(_aavePool));
        if (address(_aToken).code.length == 0) revert NotContract(address(_aToken));
        if (_aToken.UNDERLYING_ASSET_ADDRESS() != address(_underlying)) {
            revert InvalidATokenUnderlying();
        }

        aavePool = _aavePool;
        aToken = _aToken;

        // Approve underlying token to Aave Pool (for supply).
        _underlying.forceApprove(address(_aavePool), type(uint256).max);
    }

    // =============================================================
    //                  BaseStrategy HOOKS
    // =============================================================

    /// @inheritdoc BaseStrategy
    /// @dev Tracks the scaled balance Aave mints for THIS specific `supply`
    ///      call by snapshotting before/after `scaledBalanceOf`. Concurrent
    ///      donations (separate transactions) inflate both snapshots equally,
    ///      so the delta still reflects only the amount attributable to this
    ///      call.
    function _doDeposit(uint256 _amount) internal override {
        uint256 scaledBalanceBeforeSupply = aToken.scaledBalanceOf(address(this));
        aavePool.supply(address(underlyingToken), _amount, address(this), 0);
        uint256 scaledBalanceAfterSupply = aToken.scaledBalanceOf(address(this));
        uint256 scaledBalanceMinted = scaledBalanceAfterSupply - scaledBalanceBeforeSupply;
        if (scaledBalanceMinted == 0) revert AaveSupplyZeroScaledBalance(_amount);

        _ownScaledBalance += scaledBalanceMinted;
        emit OwnScaledBalanceUpdated(_ownScaledBalance);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Withdraws no more than the Strategy's Aave-accounted value and no
    ///      more than the reserve's currently liquid underlying. Aave V3 does
    ///      not partially fill ordinary withdraw requests; over-asking or
    ///      hitting an illiquid reserve reverts. Capping here gives the same
    ///      partial-withdraw semantics as ERC-4626 `maxWithdraw` without
    ///      treating utilization as a solvency loss.
    function _doWithdraw(uint256 _amount) internal override returns (uint256 actual) {
        uint256 withdrawAmount = _amount;

        uint256 accountingValue = _ownedAaveAccountingValue();
        if (accountingValue < withdrawAmount) withdrawAmount = accountingValue;

        uint256 liquidUnderlying = _aaveLiquidUnderlying();
        if (liquidUnderlying < withdrawAmount) withdrawAmount = liquidUnderlying;
        if (withdrawAmount == 0) return 0;

        actual = _withdrawFromAave(withdrawAmount);
    }

    /// @inheritdoc BaseStrategy
    /// @dev Computes underlying value from the locally tracked scaled balance,
    ///      capped at Aave's current `scaledBalanceOf` of this contract so
    ///      that an Aave-side scaled-balance shrink is reflected immediately.
    ///      This is an Aave accounting value, not a reserve-liquidity or
    ///      protocol-deficit oracle: Aave deficits that do not reduce scaled
    ///      balances / normalized income must be handled by monitoring and
    ///      `Vault.writeoffStrategyPrincipal`.
    function _estimatedTotalUnderlying() internal view override returns (uint256) {
        return _ownedAaveAccountingValue();
    }

    function _ownedAaveAccountingValue() internal view returns (uint256) {
        uint256 currentAaveScaledBalance = aToken.scaledBalanceOf(address(this));
        uint256 effectiveScaledBalance =
            _ownScaledBalance < currentAaveScaledBalance ? _ownScaledBalance : currentAaveScaledBalance;
        if (effectiveScaledBalance == 0) return 0;
        return _aaveAccountingValue(effectiveScaledBalance);
    }

    function _aaveAccountingValue(uint256 _scaledBalance) internal view returns (uint256) {
        uint256 normalizedReserveIncome = aavePool.getReserveNormalizedIncome(address(underlyingToken));
        return Math.mulDiv(_scaledBalance, normalizedReserveIncome, _RAY);
    }

    function _aaveLiquidUnderlying() internal view returns (uint256) {
        return underlyingToken.balanceOf(address(aToken));
    }

    function _withdrawFromAave(uint256 _amount) internal returns (uint256 actual) {
        uint256 underlyingBalanceBeforeWithdraw = underlyingToken.balanceOf(address(this));
        uint256 scaledBalanceBeforeWithdraw = aToken.scaledBalanceOf(address(this));
        uint256 reported = aavePool.withdraw(address(underlyingToken), _amount, address(this));
        uint256 scaledBalanceAfterWithdraw = aToken.scaledBalanceOf(address(this));
        uint256 underlyingBalanceAfterWithdraw = underlyingToken.balanceOf(address(this));

        uint256 actualBurnedScaledBalance = scaledBalanceBeforeWithdraw - scaledBalanceAfterWithdraw;
        actual = underlyingBalanceAfterWithdraw - underlyingBalanceBeforeWithdraw;
        if (actual != 0 && actualBurnedScaledBalance == 0) revert AaveWithdrawZeroScaledBurn(actual);

        _ownScaledBalance =
            actualBurnedScaledBalance > _ownScaledBalance ? 0 : _ownScaledBalance - actualBurnedScaledBalance;
        emit OwnScaledBalanceUpdated(_ownScaledBalance);

        if (reported == 0 && actual != 0) revert AaveWithdrawZeroReported(actual);
    }

    /// @inheritdoc BaseStrategy
    /// @dev aToken is the Aave position/accounting token, not a reward token.
    ///      It must leave the Strategy only through Aave withdraw paths.
    function _isSweepProtectedToken(address _token) internal view override returns (bool) {
        return super._isSweepProtectedToken(_token) || _token == address(aToken);
    }

    // =============================================================
    //                   REWARD CLAIM FUNCTIONS
    // =============================================================

    /**
     * @notice Claim Aave rewards earned by this Strategy's aToken position.
     * @dev The rewards asset list is fixed to this Strategy's aToken so the
     *      owner cannot accidentally claim rewards for an unrelated Aave
     *      position through this adapter. Ordinary reward tokens are swept to
     *      the Vault treasury; underlying rewards are treated as yield and sent
     *      to the Vault buffer without reducing principal.
     * @param _rewardsController Aave V3 rewards controller.
     * @param _amount Amount requested from Aave, or `type(uint256).max` for all
     *        currently claimable rewards.
     * @param _reward Reward token to claim.
     * @return claimed Amount reported by the rewards controller.
     * @return settled Amount actually received by treasury or Vault.
     */
    function claimAaveRewards(IAaveRewardsController _rewardsController, uint256 _amount, address _reward)
        external
        onlyOwner
        nonReentrantStrategy
        returns (uint256 claimed, uint256 settled)
    {
        if (address(_rewardsController) == address(0)) revert ZeroAddress();
        if (address(_rewardsController).code.length == 0) revert InvalidAaveRewardsController();
        if (_reward == address(0)) revert ZeroAddress();

        address underlyingAddress = address(underlyingToken);
        if (_reward != underlyingAddress && _isSweepProtectedToken(_reward)) revert CannotSweepProtectedToken();

        address[] memory assets = new address[](1);
        assets[0] = address(aToken);

        uint256 balanceBeforeClaim = IERC20(_reward).balanceOf(address(this));
        claimed = _rewardsController.claimRewards(assets, _amount, address(this), _reward);

        if (_reward == underlyingAddress) {
            uint256 balanceAfterClaim = IERC20(_reward).balanceOf(address(this));
            uint256 claimedUnderlying =
                balanceAfterClaim > balanceBeforeClaim ? balanceAfterClaim - balanceBeforeClaim : 0;
            settled = _sendUnderlyingToVault(claimedUnderlying);
            emit AaveUnderlyingRewardsClaimed(address(_rewardsController), _reward, _amount, claimed, settled);
        } else {
            settled = _sweepRewardToken(IERC20(_reward), type(uint256).max);
            emit AaveRewardsClaimed(address(_rewardsController), _reward, _amount, claimed, settled);
        }
    }

    // =============================================================
    //                   EMERGENCY FUNCTIONS
    // =============================================================

    /**
     * @notice Withdraw the currently liquid Aave position (including any
     *         liquid third-party donations) and immediately push all idle
     *         underlying back to the Vault. The Vault receipt is accounted as
     *         returned principal; if the remaining Aave-accounted position is
     *         later deemed unrecoverable, a Vault WRITEOFF_ROLE holder must call
     *         `Vault.writeoffStrategyPrincipal(...)` for that residual.
     * @dev    Owner only. Pushing through `receiveFromStrategy` keeps the
     *         Vault-side valuation cache in sync and avoids an observable
     *         window where funds sit idle in the Strategy but are excluded from
     *         `CollateralVault.backingRatio()`.
     */
    function emergencyWithdrawFromAave() external onlyOwner nonReentrantStrategy returns (uint256 sent) {
        uint256 aTokenBalance = aToken.balanceOf(address(this));
        uint256 liquidUnderlying = _aaveLiquidUnderlying();
        uint256 withdrawAmount = aTokenBalance < liquidUnderlying ? aTokenBalance : liquidUnderlying;
        if (withdrawAmount != 0) {
            _withdrawFromAave(withdrawAmount);
        }

        uint256 idleUnderlying = underlyingToken.balanceOf(address(this));
        if (idleUnderlying == 0) return 0;

        sent = _returnUnderlyingPrincipalToVault(idleUnderlying);
    }
}
"
    },
    "src/Strategies/BaseStrategy.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity 0.8.24;

import "openzeppelin-contracts/contracts/token/ERC20/IERC20.sol";
import "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import "openzeppelin-contracts/contracts/access/IAccessControl.sol";
import "openzeppelin-contracts-upgradeable/access/OwnableUpgradeable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/Initializable.sol";
import "openzeppelin-contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

import "../Interfaces/IStrategy.sol";
import "../Interfaces/ICollateralVault.sol";

interface IMerklDistributor {
    function claim(
        address[] calldata users,
        address[] calldata tokens,
        uint256[] calldata amounts,
        bytes32[][] calldata proofs
    ) external;
}

/**
 * @title BaseStrategy - Push-model Strategy base contract (Upgradeable)
 * @notice Implements the push model for all derived strategies.
 *
 *   - `deposit(declared, received)`: onlyVault. Underlying is transferred BEFORE this call.
 *                                  Runs `_doDeposit(received)` in an isolated self-call; on
 *                                  rejection, returns the exact receipt to the Vault or reverts.
 *   - `sendToVault(amount)`     : WITHDRAWER_ROLE on Vault.
 *                                  Withdraws from the upstream protocol via `_doWithdraw`,
 *                                  reduces `principal` (principal-first), pushes the result
 *                                  to the Vault via `receiveFromStrategy`.
 *   - `sendProfitToVault()`     : HARVESTER_ROLE on Vault.
 *                                  Caps the amount at `realizedYield()`, withdraws via
 *                                  `_doWithdraw`, leaves `principal` unchanged, pushes
 *                                  the result directly to the Vault buffer.
 *   - `writeoffPrincipal(amt)`  : onlyVault. Acknowledges a permanent loss so the Strategy
 *                                  can later be removed. Returns the clamped amount written off.
 *
 *   Derived contracts only implement three hooks:
 *     `_doDeposit(amount)`
 *     `_doWithdraw(amount) -> actual`
 *     `_estimatedTotalUnderlying() view -> uint256`
 */
abstract contract BaseStrategy is Initializable, IStrategy, OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;

    // =============================================================
    //                          STATE
    // =============================================================

    /// @notice Vault address managing this Strategy
    address public vault;

    /// @notice Underlying token under management
    IERC20 public underlyingToken;

    /// @notice Principal currently tracked by this Strategy
    /// @dev    Increased on `deposit`, decreased on `sendToVault` and `writeoffPrincipal`.
    ///         `sendProfitToVault` does not change this.
    uint256 internal _principal;

    /// @notice Pending owner for two-step ownership transfer
    address private _pendingOwner;

    /// @notice Address authorized to upgrade this Strategy implementation.
    address public upgrader;

    /// @dev Local reentrancy guard for Strategy entry points that call external protocols or tokens.
    uint256 private _reentrancyStatus;

    /// @dev Storage gap for future upgrades.
    uint256[46] private __gap;

    // =============================================================
    //                          CONSTANTS
    // =============================================================

    /// @dev Legacy role retained only for archived async strategy request functions.
    bytes32 internal constant _ALLOCATOR_ROLE = keccak256("ALLOCATOR_ROLE");
    /// @dev Must match the operation-specific roles on CollateralVault.
    bytes32 internal constant _WITHDRAWER_ROLE = keccak256("WITHDRAWER_ROLE");
    bytes32 internal constant _HARVESTER_ROLE = keccak256("HARVESTER_ROLE");
    uint256 public constant MAX_MERKL_TOKENS_PER_CLAIM = 16;

    // =============================================================
    //                          EVENTS
    // =============================================================

    event Deposited(uint256 amount, uint256 newPrincipal);
    event SentToVault(address indexed caller, uint256 requested, uint256 actual, uint256 newPrincipal);
    event ProfitSentToVault(address indexed caller, uint256 yield, uint256 actual);
    event PrincipalWrittenOff(uint256 amount, uint256 newPrincipal);
    event PrincipalReturned(uint256 amount, uint256 newPrincipal);
    event EmergencyWithdrawn(uint256 amount);
    event RewardTokenSwept(address indexed token, address indexed treasury, uint256 requested, uint256 received);
    event MerklRewardsClaimed(
        address indexed distributor, address indexed token, uint256 cumulativeAmount, uint256 swept
    );
    event MerklUnderlyingRewardsClaimed(
        address indexed distributor, address indexed token, uint256 cumulativeAmount, uint256 sentToVault
    );
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event UpgraderUpdated(address indexed oldUpgrader, address indexed newUpgrader);

    // =============================================================
    //                          ERRORS
    // =============================================================

    error OnlyVault();
    error Unauthorized();
    error ZeroAddress();
    error NotContract(address target);
    error ReentrantCall();
    error CannotSweepProtectedToken();
    error RenounceOwnershipDisabled();
    error InvalidMerklDistributor();
    error InvalidMerklClaim();
    error DuplicateMerklToken(address token);
    error TooManyMerklTokens(uint256 tokenCount, uint256 maxTokenCount);
    error DepositRecoveryFailed();

    // =============================================================
    //                        MODIFIERS
    // =============================================================

    modifier onlyVault() {
        if (msg.sender != vault) revert OnlyVault();
        _;
    }

    modifier onlyVaultRole(bytes32 role) {
        if (!IAccessControl(vault).hasRole(role, msg.sender)) revert Unauthorized();
        _;
    }

    modifier nonReentrantStrategy() {
        if (_reentrancyStatus == 1) revert ReentrantCall();
        _reentrancyStatus = 1;
        _;
        _reentrancyStatus = 0;
    }

    // =============================================================
    //                       CONSTRUCTOR
    // =============================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // =============================================================
    //                      INITIALIZER
    // =============================================================

    /**
     * @notice BaseStrategy initialization function
     * @param _vault Vault address managing this Strategy
     * @param _underlying Underlying token under management
     * @param _owner Strategy manager (for emergency operations)
     * @param _upgrader Strategy upgrade authority
     */
    function __BaseStrategy_init(address _vault, IERC20 _underlying, address _owner, address _upgrader)
        internal
        onlyInitializing
    {
        __Ownable_init();
        __UUPSUpgradeable_init();

        if (_vault == address(0)) revert ZeroAddress();
        if (address(_underlying) == address(0)) revert ZeroAddress();
        if (_owner == address(0)) revert ZeroAddress();
        if (_upgrader == address(0)) revert ZeroAddress();
        if (_vault.code.length == 0) revert NotContract(_vault);
        if (address(_underlying).code.length == 0) revert NotContract(address(_underlying));

        vault = _vault;
        underlyingToken = _underlying;
        upgrader = _upgrader;
        _transferOwnership(_owner);

        // Pre-approve Vault so `receiveFromStrategy` can pull underlying via
        // `safeTransferFrom`. The Vault is a trusted contract (UUPS, GOV-controlled).
        _underlying.forceApprove(_vault, type(uint256).max);
    }

    // =============================================================
    //                    UUPS UPGRADE
    // =============================================================

    function _authorizeUpgrade(address) internal view override {
        if (msg.sender != upgrader) revert Unauthorized();
    }

    function setUpgrader(address _newUpgrader) external {
        if (msg.sender != upgrader) revert Unauthorized();
        if (_newUpgrader == address(0)) revert ZeroAddress();

        address oldUpgrader = upgrader;
        upgrader = _newUpgrader;
        emit UpgraderUpdated(oldUpgrader, _newUpgrader);
    }

    // =============================================================
    //                    OWNERSHIP OVERRIDES
    // =============================================================

    /**
     * @notice Pending owner for two-step ownership transfer.
     */
    function pendingOwner() public view returns (address) {
        return _pendingOwner;
    }

    /**
     * @notice Start a two-step ownership transfer.
     * @dev Passing address(0) cancels an existing pending transfer, matching
     *      OpenZeppelin Ownable2Step behavior.
     */
    function transferOwnership(address newOwner) public override onlyOwner {
        _pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner(), newOwner);
    }

    /**
     * @notice Accept a pending ownership transfer.
     */
    function acceptOwnership() public {
        require(_pendingOwner == _msgSender(), "Ownable2Step: caller is not the new owner");
        _transferOwnership(_msgSender());
    }

    /**
     * @notice Disable ownership renounce to preserve emergency, reward-sweep,
     *         and upgrade controls.
     */
    function renounceOwnership() public view override onlyOwner {
        revert RenounceOwnershipDisabled();
    }

    function _transferOwnership(address newOwner) internal override {
        delete _pendingOwner;
        super._transferOwnership(newOwner);
    }

    // =============================================================
    //                    IStrategy VIEW FUNCTIONS
    // =============================================================

    /// @inheritdoc IStrategy
    function underlying() external view override returns (address) {
        return address(underlyingToken);
    }

    /// @inheritdoc IStrategy
    function principal() external view override returns (uint256) {
        return _principal;
    }

    /// @inheritdoc IStrategy
    function realizedYield() public view override returns (uint256) {
        uint256 total = _estimatedTotalUnderlying();
        return total > _principal ? total - _principal : 0;
    }

    /// @inheritdoc IStrategy
    function estimatedTotalUnderlying() external view override returns (uint256) {
        return _estimatedTotalUnderlying();
    }

    // =============================================================
    //                    IStrategy MUTATING FUNCTIONS
    // =============================================================

    /// @inheritdoc IStrategy
    function deposit(uint256 _declaredAmount, uint256 _receivedAmount)
        external
        override
        onlyVault
        nonReentrantStrategy
        returns (uint256 deposited)
    {
        if (_receivedAmount == 0) {
            if (_declaredAmount != 0) revert DepositRecoveryFailed();
            return 0;
        }

        try this.deployUnderlying(_receivedAmount) {
            _principal += _receivedAmount;
            emit Deposited(_receivedAmount, _principal);
            return _receivedAmount;
        } catch {
            if (_declaredAmount != _receivedAmount) revert DepositRecoveryFailed();
            uint256 vaultBalanceBeforeRecovery = underlyingToken.balanceOf(vault);
            uint256 strategyBalanceBeforeRecovery = underlyingToken.balanceOf(address(this));
            (bool transferSucceeded, bytes memory transferReturnData) =
                address(underlyingToken).call(abi.encodeCall(IERC20.transfer, (vault, _receivedAmount)));
            if (
                !transferSucceeded
                    || (transferReturnData.length != 0
                        && (transferReturnData.length < 32 || !abi.decode(transferReturnData, (bool))))
            ) {
                revert DepositRecoveryFailed();
            }
            uint256 vaultBalanceAfterRecovery = underlyingToken.balanceOf(vault);
            uint256 strategyBalanceAfterRecovery = underlyingToken.balanceOf(address(this));
            if (
                vaultBalanceAfterRecovery < vaultBalanceBeforeRecovery
                    || strategyBalanceAfterRecovery > strategyBalanceBeforeRecovery
                    || vaultBalanceAfterRecovery - vaultBalanceBeforeRecovery != _receivedAmount
                    || strategyBalanceBeforeRecovery - strategyBalanceAfterRecovery != _receivedAmount
            ) {
                revert DepositRecoveryFailed();
            }
            return 0;
        }
    }

    /// @notice Execute the protocol-specific deposit in an isolated call frame.
    /// @dev Self-only so an upstream revert rolls back its effects while the
    ///      outer `deposit` frame can return the idle Underlying to the Vault.
    function deployUnderlying(uint256 _amount) external {
        if (msg.sender != address(this)) revert Unauthorized();
        _doDeposit(_amount);
    }

    /// @inheritdoc IStrategy
    function sendToVault(uint256 _amount)
        external
        override
        nonReentrantStrategy
        onlyVaultRole(_WITHDRAWER_ROLE)
        returns (uint256 sent)
    {
        if (_amount == 0) return 0;

        uint256 withdrawnUnderlying = _doWithdraw(_amount);
        if (withdrawnUnderlying == 0) {
            emit SentToVault(msg.sender, _amount, 0, _principal);
            return 0;
        }

        // Push first, then decrement `_principal` using the amount the Vault
        // actually received (`sent`). Decrementing based on `actual` alone
        // would drop principal even when fee-on-transfer / rebasing / hook
        // tokens deliver less than `actual` to the Vault, producing silent
        // accounting drift between Strategy.principal and Vault.bufferBalance.
        // Principal-first decrement: any excess of `sent` over the remaining
        // `_principal` represents yield that is being deallocated as part of
        // this amount-specified push and stays in the Vault buffer to be
        // handled by `transferYieldToTreasury`.
        sent = ICollateralVault(vault).receiveFromStrategy(withdrawnUnderlying);
        uint256 principalReduction = sent > _principal ? _principal : sent;
        _principal -= principalReduction;

        emit SentToVault(msg.sender, _amount, sent, _principal);
    }

    /// @inheritdoc IStrategy
    function sendProfitToVault()
        external
        override
        nonReentrantStrategy
        onlyVaultRole(_HARVESTER_ROLE)
        returns (uint256 sent)
    {
        uint256 realizedProfit = realizedYield();
        if (realizedProfit == 0) {
            emit ProfitSentToVault(msg.sender, 0, 0);
            return 0;
        }

        uint256 withdrawnUnderlying = _doWithdraw(realizedProfit);
        if (withdrawnUnderlying == 0) {
            emit ProfitSentToVault(msg.sender, realizedProfit, 0);
            return 0;
        }

        // A converter's loss allowance can withdraw more than the measured yield.
        // Return that excess as principal instead of leaving phantom principal behind.
        if (withdrawnUnderlying > realizedProfit) {
            uint256 returned = ICollateralVault(vault).receiveFromStrategy(withdrawnUnderlying - realizedProfit);
            _accountReturnedPrincipal(returned);
            withdrawnUnderlying = realizedProfit;
        }

        // The remaining yield-only push leaves `_principal` unchanged. Send
        // directly to the Vault buffer so Strategy valuation cache is not
        // reduced as if principal had been returned.
        sent = _sendUnderlyingToVault(withdrawnUnderlying);
        emit ProfitSentToVault(msg.sender, realizedProfit, sent);
    }

    /// @inheritdoc IStrategy
    function writeoffPrincipal(uint256 _amount)
        external
        override
        onlyVault
        nonReentrantStrategy
        returns (uint256 writtenOff)
    {
        writtenOff = _amount > _principal ? _principal : _amount;
        _principal -= writtenOff;
        emit PrincipalWrittenOff(writtenOff, _principal);
    }

    // =============================================================
    //                   EMERGENCY FUNCTIONS
    // =============================================================

    /**
     * @notice Emergency push of Underlying held directly by this Strategy
     *         (not deployed in the upstream protocol) back to the Vault.
     *         Used to recover funds that became idle in the Strategy contract
     *         — e.g. after `emergencyWithdrawFromAave`, a donation, or an
     *         upstream protocol incident.
     * @dev    Owner only. The destination is fixed to `vault`; the previous
     *         arbitrary `_to` parameter allowed a Strategy owner (who can be
     *         distinct from the Vault GOV in some deployments) to drain
     *         Underlying to any address without GOV approval.
     *
     *         `_principal` is intentionally NOT decremented. This operation
     *         only moves recoverable idle Underlying back into Vault custody;
     *         it does not assert that the Strategy's upstream principal has
     *         been repaid or permanently lost.
     *
     *         Route through `Vault.receiveFromStrategy` instead of transferring
     *         directly so the Vault reduces an exact-delivery cache or
     *         invalidates it when declared and received amounts differ. A stale
     *         pre-recovery cache must not be able to count the same underlying
     *         once in the Vault buffer and again as Strategy value if live
     *         Strategy valuation is unavailable.
     *
     *         If the upstream balance is also gone and the residual loss needs
     *         to be acknowledged, the incident writeoff role should follow up with
     *         `Vault.writeoffStrategyPrincipal(strategy, amount, minBackingRatioAfter)`.
     */
    function emergencyWithdraw(uint256 _amount) external onlyOwner nonReentrantStrategy {
        if (_amount == 0) return;
        uint256 sent = ICollateralVault(vault).receiveFromStrategy(_amount);
        _afterEmergencyUnderlyingSent(_amount, sent);
        emit EmergencyWithdrawn(sent);
    }

    /**
     * @notice Sweep non-underlying, non-position reward tokens to the Vault treasury.
     * @dev    Covers Aave incentives, Merkl rewards, or accidental reward-token
     *         transfers that have already landed in the Strategy. Underlying and
     *         protocol position/accounting tokens are deliberately excluded:
     *         principal and underlying yield must return through `sendToVault`,
     *         `sendProfitToVault`, or `emergencyWithdraw`.
     *         Pass `type(uint256).max` to sweep the Strategy's full token balance.
     */
    function sweepRewardToken(IERC20 _token, uint256 _amount)
        external
        override
        onlyOwner
        nonReentrantStrategy
        returns (uint256 swept)
    {
        swept = _sweepRewardToken(_token, _amount);
    }

    /**
     * @notice Claim Merkl rewards earned by this Strategy. Ordinary reward
     *         tokens are swept to the current Vault treasury; underlying rewards
     *         are pushed back to the Vault as yield.
     * @dev    Uses Merkl's basic `claim` entry point only: every `user` is forced
     *         to `address(this)`, so no custom recipient or callback data can be
     *         injected. Upstream position/accounting tokens are rejected before
     *         the distributor call; underlying-token rewards are allowed but must
     *         are sent directly to the Vault buffer instead of the treasury
     *         sweep path, preserving the principal/yield accounting boundary for
     *         Morpho/Euler/Merkl-style reward programs without reducing the
     *         Vault's Strategy valuation cache.
     * @param  _distributor Merkl distributor contract.
     * @param  _tokens Reward tokens being claimed.
     * @param  _amounts Cumulative Merkl claim amounts for this Strategy.
     * @param  _proofs Merkle proofs matching each `(strategy, token, amount)`.
     * @return settledAmounts Amounts actually received by treasury or Vault per token.
     */
    function claimMerklRewards(
        IMerklDistributor _distributor,
        address[] calldata _tokens,
        uint256[] calldata _amounts,
        bytes32[][] calldata _proofs
    ) external onlyOwner nonReentrantStrategy returns (uint256[] memory settledAmounts) {
        if (address(_distributor) == address(0)) revert ZeroAddress();
        if (address(_distributor).code.length == 0) revert InvalidMerklDistributor();

        uint256 length = _tokens.length;
        if (length == 0 || length != _amounts.length || length != _proofs.length) revert InvalidMerklClaim();
        if (length > MAX_MERKL_TOKENS_PER_CLAIM) {
            revert TooManyMerklTokens(length, MAX_MERKL_TOKENS_PER_CLAIM);
        }

        address[] memory users = new address[](length);
        uint256[] memory balancesBeforeClaim = new uint256[](length);
        address underlyingAddress = address(underlyingToken);
        for (uint256 i = 0; i < length;) {
            address token = _tokens[i];
            if (token == address(0)) revert ZeroAddress();
            if (token != underlyingAddress && _isSweepProtectedToken(token)) revert CannotSweepProtectedToken();
            for (uint256 j = 0; j < i;) {
                if (_tokens[j] == token) revert DuplicateMerklToken(token);
                unchecked {
                    ++j;
                }
            }
            balancesBeforeClaim[i] = IERC20(token).balanceOf(address(this));
            users[i] = address(this);
            unchecked {
                ++i;
            }
        }

        _distributor.claim(users, _tokens, _amounts, _proofs);

        settledAmounts = new uint256[](length);
        for (uint256 i = 0; i < length;) {
            settledAmounts[i] = _settleClaimedMerklToken(
                address(_distributor), _tokens[i], _amounts[i], balancesBeforeClaim[i], underlyingAddress
            );
            unchecked {
                ++i;
            }
        }
    }

    function _settleClaimedMerklToken(
        address _distributor,
        address _token,
        uint256 _cumulativeAmount,
        uint256 _balanceBeforeClaim,
        address _underlyingAddress
    ) internal returns (uint256 settled) {
        if (_token == _underlyingAddress) {
            uint256 balanceAfterClaim = IERC20(_token).balanceOf(address(this));
            uint256 claimedUnderlying =
                balanceAfterClaim > _balanceBeforeClaim ? balanceAfterClaim - _balanceBeforeClaim : 0;
            if (claimedUnderlying != 0) {
                settled = _sendUnderlyingToVault(claimedUnderlying);
            }
            emit MerklUnderlyingRewardsClaimed(_distributor, _token, _cumulativeAmount, settled);
        } else {
            settled = _sweepRewardToken(IERC20(_token), type(uint256).max);
            emit MerklRewardsClaimed(_distributor, _token, _cumulativeAmount, settled);
        }
    }

    function _sendUnderlyingToVault(uint256 _amount) internal returns (uint256 sent) {
        if (_amount == 0) return 0;

        uint256 vaultBalanceBefore = underlyingToken.balanceOf(vault);
        underlyingToken.safeTransfer(vault, _amount);
        uint256 vaultBalanceAfter = underlyingToken.balanceOf(vault);
        sent = vaultBalanceAfter > vaultBalanceBefore ? vaultBalanceAfter - vaultBalanceBefore : 0;
    }

    function _accountReturnedPrincipal(uint256 _received) internal returns (uint256 principalReturned) {
        if (_received == 0) return 0;

        principalReturned = _received > _principal ? _principal : _received;
        if (principalReturned == 0) return 0;

        _principal -= principalReturned;
        emit PrincipalReturned(principalReturned, _principal);
    }

    /// @dev Common settlement path for protocol-specific emergency recovery.
    ///      This differs from `emergencyWithdraw`: recovered upstream principal
    ///      reduces `_principal` by the Vault's actual received amount.
    function _returnUnderlyingPrincipalToVault(uint256 _amount) internal returns (uint256 sent) {
        if (_amount == 0) return 0;

        sent = ICollateralVault(vault).receiveFromStrategy(_amount);
        _afterEmergencyUnderlyingSent(_amount, sent);
        _accountReturnedPrincipal(sent);
        emit EmergencyWithdrawn(sent);
    }

    /**
     * @dev Shared reward-token sweep primitive for future claim adapters.
     *      Protocol-specific strategies may claim rewards into this contract and
     *      call this helper, preserving the same accounting boundary and fixed
     *      treasury destination as the external owner operation. Derived
     *      strategies must mark any receipt/accounting token that represents the
     *      upstream position as sweep-protected.
     */
    function _sweepRewardToken(IERC20 _token, uint256 _amount) internal returns (uint256 swept) {
        address tokenAddress = address(_token);
        if (tokenAddress == address(0)) revert ZeroAddress();
        if (_isSweepProtectedToken(tokenAddress)) revert CannotSweepProtectedToken();

        uint256 amount = _amount == type(uint256).max ? _token.balanceOf(address(this)) : _amount;
        if (amount == 0) return 0;

        address recipient = ICollateralVault(vault).treasury();
        if (recipient == address(0)) revert ZeroAddress();

        uint256 recipientBalanceBeforeSweep = _token.balanceOf(recipient);
        _token.safeTransfer(recipient, amount);
        uint256 recipientBalanceAfterSweep = _token.balanceOf(recipient);
        swept = recipientBalanceAfterSweep > recipientBalanceBeforeSweep
            ? recipientBalanceAfterSweep - recipientBalanceBeforeSweep
            : 0;

        emit RewardTokenSwept(tokenAddress, recipient, amount, swept);
    }

    /**
     * @dev Tokens that are not rewards and must not be routed to treasury.
     *      Derived strategies override this to protect protocol-specific
     *      receipt/accounting tokens such as Aave aTokens.
     */
    function _isSweepProtectedToken(address _token) internal view virtual returns (bool) {
        return _token == address(underlyingToken) || _token == address(ICollateralVault(vault).dToken());
    }

    /// @dev Optional hook for derived strategies that separately track idle
    ///      underlying held by the Strategy contract itself.
    function _afterEmergencyUnderlyingSent(uint256, uint256) internal virtual {}

    // =============================================================
    //                   VIRTUAL HOOKS
    // =============================================================

    /// @dev Deploy `_amount` of underlying (already in this contract) into the
    ///      upstream yield protocol. Implementer is responsible for the actual
    ///      external call (e.g., `aavePool.supply(...)`).
    function _doDeposit(uint256 _amount) internal virtual;

    /// @dev Withdraw `_amount` of underlying from the upstream protocol. The
    ///      withdrawn underlying must end up held by THIS contract so the base
    ///      logic can route principal/cache-reducing returns through
    ///      `receiveFromStrategy` and yield-only returns through direct transfer.
    /// @return actual Amount actually withdrawn; may be less than requested.
    function _doWithdraw(uint256 _amount) internal virtual returns (uint256 actual);

    /// @dev Underlying value (principal + accrued yield) held in the upstream
    ///      protocol on behalf of this Strategy.
    function _estimatedTotalUnderlying() internal view virtual returns (uint256);
}
